"""Zoo 1.153.0: a stain where water runs down a wall.

`stain_streak` (`dressing.stain_grid`, `recipes/dress_cover.py`): a 6 x 6 grid 2 mm off a wall below a window's sill,
its darkening in its `Wear` colour -- `STAIN_DARK` (0.5) at its cause, 1.0 at its foot and both sides -- in the
wall's own skin renamed `<skin>_stain`, which Level Factory (>= 0.271.0) draws as black at `1 - shade` over the wall.
Patina (>= 0.39.0) orders it.

Proven: tests/test_stain_streak.py fails on 1.152.0 (fails_on_old.out.txt); the clone's Blender half, 3,172 passed
(suite_bpy_clone.out.txt), and its pure half (suite_clone.out.txt); the slice rebuilt five times (the factory's
docs/findings/slice_look/, slices 17-17e).
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / 'zoo'
PINS = {'CHANGELOG.md': 'c8d76a64ee97f6e0', 'VERSION': 'e31a628f514b7290', 'zoo_keeper/core/dressing.py': '7366fe0e2ca24c32', 'zoo_keeper/recipes/dress_cover.py': '723a8d072d2441ee'}
EDITS = {'CHANGELOG.md': [('lines 1-1', '## [1.152.0] - a leaf card lit as part of its crown\n', "## [1.153.0] - a stain where water runs down a wall\n\nThe factory's roadmap 324. Patina (>= 0.39.0) orders a `stain_streak` below a window's sill.\n\n### Added\n- **`stain_streak`** (`dressing.stain_grid`, `recipes/dress_cover.py`): a 6 x 6 grid `STAIN_PROUD` (2 mm) off the\n  wall, its darkening in its `Wear` colour -- `STAIN_DARK` at its cause, fading to 1.0 down its length and out to\n  both sides, each column jittered so it reads as runoff and not as a band. Its material is the wall's own skin,\n  named `<skin>_stain` (`STAIN_SUFFIX`): Level Factory's import (>= 0.271.0) draws it as black at `1 - shade` over\n  the wall, and a consumer that does not know the suffix draws the wall. `STAIN_DARK` is 0.5: 0.72 was chosen unseen\n  and measured faint on the slice (slice 17d: the sill row kept 0.80 of the wall under the inspection light, and at\n  evening read as nothing); at 0.5 (slice 17e) it keeps 0.64 under the inspection light and 0.18 at evening, and\n  reads as runoff under each sill, gone by the band below. Tests: tests/test_stain_streak.py (the grid, the plan's\n  wall skin, the build).\n\n## [1.152.0] - a leaf card lit as part of its crown\n")], 'VERSION': [('lines 1-1', '1.152.0', '1.153.0')], 'zoo_keeper/core/dressing.py': [('lines 115-116', 'STONE_TRIM_COLOR = (0.80, 0.76, 0.68)\n\n', 'STONE_TRIM_COLOR = (0.80, 0.76, 0.68)\n#: A STAIN WHERE WATER RUNS (1.153.0, the factory\'s roadmap 324). The walker, of the vertical slice: "Things still\n#: look simple, and computer made". A real facade darkens below whatever sheds water onto it -- a sill, a coping, a\n#: scupper -- and nowhere else; the slice\'s walls were one even field. A `stain_streak` is a grid laid `STAIN_PROUD`\n#: off the wall, its darkening in its `Wear` colour: `STAIN_DARK` at the cause, fading to 1.0 down its length and\n#: out to its sides, varied by column so it reads as runoff and not as a band. Level Factory\'s import (>= 0.271.0,\n#: `zoo_worldskin.gd`) draws it as a multiply overlay onto the wall, out of the bake, so a shade of 1.0 is the wall\n#: exactly. Its material is the WALL\'S OWN SKIN (Patina passes the slot\'s kind as `wall_material`; the colour is\n#: the wall genome\'s style): what a consumer that does not know the suffix draws is the wall, not a grey patch.\n#: Drawn opaque in that skin it shows an outline, its lighting apart from the wall\'s (the factory\'s slice 17b).\nSTAIN_COVERS = ("stain_streak",)\n#: the stain\'s material is the wall\'s skin renamed with this, which the import draws as a multiply overlay\nSTAIN_SUFFIX = "_stain"\nSTAIN_PROUD = 0.002\n#: the darkest a stain draws a wall to, at its cause (its column\'s jitter lightens it to 0.55-1.0 of that). 0.72 was\n#: chosen unseen and measured faint: on the slice\'s bank (the factory\'s slice 17d) the sill row kept 0.80 of the\n#: wall under the inspection light and 0.49 at evening, and at evening read as nothing\nSTAIN_DARK = 0.5\nSTAIN_COLS = 6\nSTAIN_ROWS = 6\n\n'), ('lines 166-167', 'STRING_INTO = 0.01\n\n', 'STRING_INTO = 0.01\n\n\ndef stain_grid(width: float, length: float, seed: int):\n    """``(verts, faces, shade)`` of a stain streak in cover-local space: x across it, y out of the wall at\n    `STAIN_PROUD`, z down from its top (0) to ``-length``; ``faces`` index quads, ``shade`` the `Wear` value a\n    vertex carries -- `STAIN_DARK` at the top of a dark column\'s middle, 1.0 at the bottom row and the side edges.\n    Pure and deterministic for a seed."""\n    import random\n    r = random.Random(int(seed))\n    cols, rows = STAIN_COLS, STAIN_ROWS\n    col_k = [0.55 + 0.45 * r.random() for _ in range(cols + 1)]\n    verts, shade = [], []\n    for j in range(rows + 1):\n        t = j / rows                                    # 0 at the cause, 1 at the streak\'s foot\n        for i in range(cols + 1):\n            u = -1.0 + 2.0 * i / cols                   # -1 .. 1 across\n            edge = max(0.0, 1.0 - u * u)\n            depth = (1.0 - STAIN_DARK) * ((1.0 - t) ** 1.4) * edge * col_k[i]\n            verts.append((u * width / 2.0, STAIN_PROUD, -t * length))\n            shade.append(round(1.0 - depth, 4))\n    faces = []\n    for j in range(rows):\n        for i in range(cols):\n            a = j * (cols + 1) + i\n            faces.append((a, a + 1, a + cols + 2, a + cols + 1))\n    return verts, faces, shade\n\n'), ('lines 327-328', '        material, color = STONE_TRIM_KIND, [round(float(c), 4) for c in STONE_TRIM_COLOR]\n    return {\n', '        material, color = STONE_TRIM_KIND, [round(float(c), 4) for c in STONE_TRIM_COLOR]\n    # and a stain is the wall\'s own skin (1.153.0): the slot\'s kind, the wall genome\'s colour for the theme, so\n    # `make_material` returns the wall\'s material by name\n    elif order.get("cover") in STAIN_COVERS:\n        from . import dna as _dna, genome as _genome, skins as _skins\n        kind = order.get("wall_material")\n        if kind in _skins.KNOWN_KINDS:\n            got = _dna.theme_style(_genome.load_species("wall"), theme)\n            wall_color = (got[1].get("color") if got else None) or [0.5, 0.49, 0.46]\n            material, color = kind, [round(float(c), 4) for c in wall_color]\n    return {\n'), ('lines 352-353', '            "head": bool(order.get("head", False)),\n        },\n', '            "head": bool(order.get("head", False)),\n            "wall_material": order.get("wall_material"),\n        },\n')], 'zoo_keeper/recipes/dress_cover.py': [('lines 130-131', '            geometry.add_box(bm, center, size)\n    elif cover == "coping":\n', '            geometry.add_box(bm, center, size)\n    elif cover == "stain_streak":\n        # where water runs down a wall (1.153.0); `size2` is [width, length]. The grid\'s own `Wear` colour is the\n        # stain, so it is finished without `wear_colors`, which would write over it.\n        import bpy\n        from ..core.dressing import STAIN_SUFFIX, stain_grid\n        width, length = (order.get("size2") or [0.8, 1.2])[:2]\n        verts, faces, shade = stain_grid(width, length, order.get("seed_offset", 0))\n        bv = [bm.verts.new(v) for v in verts]\n        layer = bm.loops.layers.color.new(geometry.WEAR_LAYER)\n        for f in faces:\n            face = bm.faces.new([bv[k] for k in f])\n            for loop, k in zip(face.loops, f):\n                s = shade[k]\n                loop[layer] = (s, s, s, 1.0)\n        # UVs as the walls take them (texel 1.0, `_arch`), for a consumer that draws the skin and not the overlay\n        geometry.cube_project_uv(bm, 1.0)\n        obj = geometry.bm_to_object(bm, f"Cover{plan.get(\'side\') or \'\'}_{cover}", collection, finish=False)\n        # THE WALL\'S SKIN UNDER ANOTHER NAME: `<skin>_stain`, which Level Factory\'s import (>= 0.271.0,\n        # `zoo_worldskin.gd`) draws as a multiply overlay of its vertex colour onto the wall\n        skin = materials.make_material(f"M_Cover_{plan[\'material\']}", plan["color"], plan["material"])\n        name = skin.name + STAIN_SUFFIX\n        mat = bpy.data.materials.get(name)\n        if mat is None:\n            mat = skin.copy()\n            mat.name = name\n        materials.assign([obj], mat)\n        return {"objects": [obj], "collision_boxes": [], "attachments": {},\n                "uv_region": order.get("uv_region")}\n    elif cover == "coping":\n')]}
WHOLE = {}
NEW_FILES = {'tests/test_stain_streak.py': '"""A stain where water runs down a wall (1.153.0, the factory\'s roadmap 324).\n\nPatina (>= 0.39.0) orders a `stain_streak` below what sheds water onto a facade -- a sill, a coping, a scupper -- naming\nthe wall\'s kind as `wall_material`. Zoo lays a grid `STAIN_PROUD` off the wall in the WALL\'S OWN SKIN, renamed with\n`STAIN_SUFFIX` so Level Factory\'s import (>= 0.271.0) draws its vertex colour as a multiply overlay onto the wall:\ndarkest at the cause, fading down and out to nothing. The pure halves run anywhere; the build under Blender.\n"""\nimport pytest\n\nfrom zoo_keeper import TOOL_VERSION\nfrom zoo_keeper.core import dna, genome\nfrom zoo_keeper.core import dressing as D\n\nSPACE = "spec/Blender Z-up raw coords"\n\n\ndef _order(**kw):\n    o = {"cover": "stain_streak", "pos": [0.0, 11.0, 4.0], "normal": [0.0, 1.0, 0.0], "size": 0.9,\n         "size2": [0.9, 1.4], "collision": "none", "seed_offset": 7, "wall_material": "concrete"}\n    o.update(kw)\n    return o\n\n\ndef test_the_stain_is_darkest_at_its_cause_and_fades_to_nothing():\n    """FAILS ON 1.152.0: no stain."""\n    verts, faces, shade = D.stain_grid(0.9, 1.4, 7)\n    cols, rows = D.STAIN_COLS, D.STAIN_ROWS\n    assert len(verts) == (cols + 1) * (rows + 1) and len(faces) == cols * rows\n    assert min(shade) >= D.STAIN_DARK - 1e-9 and min(shade) < 0.9\n    foot = shade[rows * (cols + 1):]\n    assert foot == [1.0] * (cols + 1)                                       # nothing at its foot\n    assert all(shade[j * (cols + 1)] == 1.0 and shade[j * (cols + 1) + cols] == 1.0 for j in range(rows + 1))\n    top = shade[: cols + 1]\n    assert min(top) < min(shade[2 * (cols + 1): 3 * (cols + 1)])            # darker at the cause than below it\n    assert all(abs(v[1] - D.STAIN_PROUD) < 1e-12 for v in verts)\n    assert D.stain_grid(0.9, 1.4, 7) == (verts, faces, shade) and D.stain_grid(0.9, 1.4, 8)[2] != shade\n\n\ndef test_it_wears_the_walls_own_kind_and_colour():\n    plan = D.dress_plan(_order(), genome.load_species("dress_cover"), "delco_1997", SPACE, TOOL_VERSION)\n    wall = dna.theme_style(genome.load_species("wall"), "delco_1997")[1]\n    assert plan["material"] == "concrete" and plan["color"] == [round(c, 4) for c in wall["color"]]\n    brick = D.dress_plan(_order(wall_material="brick"), genome.load_species("dress_cover"), "delco_1997", SPACE,\n                         TOOL_VERSION)\n    assert brick["material"] == "brick"\n\n\ndef test_bpy_the_stain_is_the_walls_skin_renamed_with_its_colours_and_uvs(tmp_path):\n    pytest.importorskip("bpy")\n    import bpy\n    from zoo_keeper.bpylayer import build as B\n    manifest = {"schema": "patina-dressing/1", "building_id": "t_bank", "space": SPACE, "orders": [_order()]}\n    B.build_dressing(manifest, str(tmp_path), theme="delco_1997", options={"save_blend": False})\n    objs = [o for o in bpy.data.objects if o.type == "MESH"]\n    assert objs\n    me = objs[0].data\n    assert any(m.name.endswith(D.STAIN_SUFFIX) for m in me.materials), [m.name for m in me.materials]\n    assert me.uv_layers and me.color_attributes.get("Wear") is not None\n    vals = [d.color[0] for d in me.color_attributes["Wear"].data]\n    assert min(vals) < 0.9 and max(vals) == pytest.approx(1.0)\n'}


def _sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: %s/%s has mixed line endings; nothing written" % (REPO.name, name))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text) != PINS[name]:
        raise SystemExit("REFUSED: %s/%s is %s, not the %s this patch was written against; nothing written"
                         % (REPO.name, name, _sha(text), PINS[name]))
    return text, crlf > 0


def main():
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: %s/%s: the anchor at %s is there %d times; nothing written"
                                 % (REPO.name, name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name, text in WHOLE.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: %s/%s exists already; nothing written" % (REPO.name, name))
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).parent.mkdir(parents=True, exist_ok=True)
        (REPO / name).write_bytes(text.encode("utf-8"))
    print("%s: %d files edited, %d written" % (REPO.name, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
